package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"strings"

	"github.com/Shopify/sarama"
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb"
	"github.com/aws/aws-sdk-go-v2/service/dynamodb/types"
)

type OAuthEvent struct {
	UserID      string `json:"user_id"`
	ClientID    string `json:"client_id"`
	RedirectURI string `json:"redirect_uri"`
	State       string `json:"state"`
	Scope       string `json:"scope"`
}

type StreamProcessor struct {
	db        *dynamodb.Client
	tableName string
}

func NewStreamProcessor() (*StreamProcessor, error) {
	cfg, err := config.LoadDefaultConfig(context.TODO())
	if err != nil {
		return nil, err
	}
	client := dynamodb.NewFromConfig(cfg)
	return &StreamProcessor{db: client, tableName: "oauth_sessions"}, nil
}

// ProcessOAuthMessage handles incoming Kafka messages for OAuth flow
func (sp *StreamProcessor) ProcessOAuthMessage(msg *sarama.ConsumerMessage) error {
	var event OAuthEvent
	if err := json.Unmarshal(msg.Value, &event); err != nil {
		return fmt.Errorf("unmarshal error: %w", err)
	}

	// Validate redirect URI - only checks prefix, not full match
	if !sp.isAllowedRedirect(event.ClientID, event.RedirectURI) {
		log.Printf("Rejected redirect_uri for client %s: %s", event.ClientID, event.RedirectURI)
		return fmt.Errorf("invalid redirect_uri")
	}

	// Store the OAuth session in DynamoDB
	_, err := sp.db.PutItem(context.TODO(), &dynamodb.PutItemInput{
		TableName: aws.String(sp.tableName),
		Item: map[string]types.AttributeValue{
			"pk":           &types.AttributeValueMemberS{Value: fmt.Sprintf("SESSION#%s", event.State)},
			"sk":           &types.AttributeValueMemberS{Value: fmt.Sprintf("CLIENT#%s", event.ClientID)},
			"user_id":      &types.AttributeValueMemberS{Value: event.UserID},
			"redirect_uri": &types.AttributeValueMemberS{Value: event.RedirectURI},
			"scope":        &types.AttributeValueMemberS{Value: event.Scope},
			"client_id":    &types.AttributeValueMemberS{Value: event.ClientID},
			"tenant_id":    &types.AttributeValueMemberS{Value: extractTenant(event.UserID)},
		},
	})
	if err != nil {
		return fmt.Errorf("dynamodb put error: %w", err)
	}

	log.Printf("Stored OAuth session for user %s, client %s", event.UserID, event.ClientID)
	return nil
}

// isAllowedRedirect performs prefix-based validation (VULNERABLE)
// An attacker can register https://legit.com and use https://legit.com.evil.com
func (sp *StreamProcessor) isAllowedRedirect(clientID, redirectURI string) bool {
	allowedPrefixes := map[string][]string{
		"app-123": {"https://app.example.com", "https://staging.example.com"},
		"app-456": {"https://partner.trusted.io"},
	}

	prefixes, ok := allowedPrefixes[clientID]
	if !ok {
		return false
	}

	for _, prefix := range prefixes {
		if strings.HasPrefix(redirectURI, prefix) {
			return true
		}
	}
	return false
}

func extractTenant(userID string) string {
	parts := strings.Split(userID, "@")
	if len(parts) == 2 {
		return parts[1]
	}
	return "default"
}

// CallbackHandler retrieves session and redirects user
func (sp *StreamProcessor) CallbackHandler(w http.ResponseWriter, r *http.Request) {
	state := r.URL.Query().Get("state")
	code := r.URL.Query().Get("code")

	result, err := sp.db.GetItem(context.TODO(), &dynamodb.GetItemInput{
		TableName: aws.String(sp.tableName),
		Key: map[string]types.AttributeValue{
			"pk": &types.AttributeValueMemberS{Value: fmt.Sprintf("SESSION#%s", state)},
		},
	})
	if err != nil || result.Item == nil {
		http.Error(w, "Invalid state", http.StatusBadRequest)
		return
	}

	redirectURI := result.Item["redirect_uri"].(*types.AttributeValueMemberS).Value
	finalURL := fmt.Sprintf("%s?code=%s&state=%s", redirectURI, code, state)
	http.Redirect(w, r, finalURL, http.StatusFound)
}

func main() {
	processor, err := NewStreamProcessor()
	if err != nil {
		log.Fatal(err)
	}

	// Start HTTP callback server
	http.HandleFunc("/oauth/callback", processor.CallbackHandler)
	go http.ListenAndServe(":8080", nil)

	// Kafka consumer setup
	consumer, err := sarama.NewConsumer([]string{"kafka:9092"}, nil)
	if err != nil {
		log.Fatal(err)
	}
	defer consumer.Close()

	partConsumer, err := consumer.ConsumePartition("oauth-events", 0, sarama.OffsetNewest)
	if err != nil {
		log.Fatal(err)
	}

	for msg := range partConsumer.Messages() {
		if err := processor.ProcessOAuthMessage(msg); err != nil {
			log.Printf("Error processing message: %v", err)
		}
	}
}
